// Build the gmail compose URL — token substitution + CC dedup. FROM v2
// gmailBtn.onclick (line 20576). Pure: takes form + tmpl, returns string.
//
// Helpers are inlined here because the kernel's evalBundle eval's each
// engine function via `new Function(...)` — that puts each fn in its own
// isolated scope, so cross-references to `emailTmplForType` / `defaultTmpl`
// would fail at call time. Standalone exports of those helpers exist for
// other consumers; this fn duplicates the logic on purpose.

engine.buildGmailUrl:
function buildGmailUrl(form, tmpl) {
  function _tmplFor(t, typeKey, sideKey) {
    if (t && t.byType && t.byType[typeKey] && t.byType[typeKey][sideKey]) return t.byType[typeKey][sideKey];
    return (t && t[sideKey]) || { subject: "", body: "" };
  }
  function _default(sideKey) {
    if (sideKey === "thirdParty") return {
      subject: "[Entity] and [TP Entity] -- [Type] ([CP Ref]) ([Date])",
      body: "Hello [TP Contact],\n\nAt the request of [Requester], attached please find a [Type] between [Entity] and [TP Entity].\n\nPlease review and let us know if it is acceptable.\n\nThanks,\n[My Name]",
    };
    return {
      subject: "[Entity] and [TP Entity] -- [Type] ([CP Ref])",
      body: "Hello [Requester],\n\nPlease find attached a draft [Type] with [TP Entity].\n\nCan you please review and let me know if you have any questions or concerns?\n\nThanks,\n[My Name]",
    };
  }
  var isToRequester = form.dest === "req";
  var side = isToRequester ? "requester" : "thirdParty";
  var typeKey = form.type || "";
  var active = _tmplFor(tmpl, typeKey, side);
  if (!active.subject && !active.body) active = _default(side);
  var subj = active.subject || "";
  var body = active.body || "";

  var entity = form.entity || "Colgate";
  var tpEntity = form.third_party_entity || "[Third Party Entity]";
  var tpFullName = form.contact_full_name || "[Contact]";
  var tpFirst = String(tpFullName).trim().split(/\s+/)[0];
  var tpEmail = (form.contact_email || "").trim();
  var cpRef = form.cp_ref || "N/A";
  var reqFirst = String(form.requester_name || "[Requester]").trim().split(/\s+/)[0];
  var today = new Date().toLocaleDateString();
  var myName = (tmpl && tmpl.myName || "").trim();
  if (tmpl && !tmpl.useFullName) myName = myName.split(/\s+/)[0] || myName;

  var map = {
    "\\[Entity\\]": entity,
    "\\[TP Entity\\]": tpEntity,
    "\\[Type\\]": form.type || "",
    "\\[CP Ref\\]": cpRef,
    "\\[Date\\]": today,
    "\\[TP Contact\\]": tpFirst,
    "\\[Requester\\]": reqFirst,
    "\\[My Name\\]": myName,
    // FROM v2 line 20669 — clinical templates use [Protocol] token; init
    // resolves the value via Word.run scan and passes it as form.protocol.
    "\\[Protocol\\]": form.protocol || "",
  };
  Object.keys(map).forEach(function (k) {
    var re = new RegExp(k, "g");
    subj = subj.replace(re, map[k]);
    body = body.replace(re, map[k]);
  });

  // CC list — always include tech_agreements@colpal.com, dedupe vs TO.
  var to = isToRequester ? (form.requester_email || "") : tpEmail;
  var ccList = [];
  if (form.requester_email && form.requester_email.length > 3 && !isToRequester) {
    ccList.push(form.requester_email);
  }
  if (form.additional_ccs) {
    var matches = String(form.additional_ccs).match(/([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9._-]+)/gi);
    if (matches) ccList.push.apply(ccList, matches);
  }
  ccList.push("tech_agreements@colpal.com");
  var seen = {};
  var toLower = String(to).toLowerCase().trim();
  var uniq = ccList.filter(function (e) {
    var s = String(e).toLowerCase().trim();
    if (!s || s === toLower || seen[s]) return false;
    seen[s] = true;
    return true;
  });
  return "https://mail.google.com/mail/?view=cm&fs=1" +
    "&to=" + encodeURIComponent(to) +
    "&cc=" + encodeURIComponent(uniq.join(",")) +
    "&su=" + encodeURIComponent(subj) +
    "&body=" + encodeURIComponent(body);
}

// FROM v2 line 20242 — MIME-string scrub. AI sometimes returns mojibake
// like "application/vnd.openxmlformats-..." in agreement_type / type
// because the upstream document fetch leaked a Content-Type header into
// the prompt. Detect + blank those values so they don't poison the
// dropdown / URL build.
//
// Returns { cleaned, scrubbed } — caller can toast each scrubbed key.

engine.cleanAiPrefill:
function cleanAiPrefill(prefill) {
  var cleaned = {};
  if (!prefill || typeof prefill !== "object") return { cleaned: cleaned, scrubbed: [] };
  Object.keys(prefill).forEach(function (k) { cleaned[k] = prefill[k]; });
  var scrubbed = [];
  ["agreement_type", "type"].forEach(function (key) {
    if (!cleaned[key]) return;
    var v = String(cleaned[key]).toLowerCase();
    if (v.indexOf("application/") !== -1 || v.indexOf("vnd.") !== -1 || v.indexOf("openxml") !== -1) {
      cleaned[key] = "";
      scrubbed.push(key);
    }
  });
  return { cleaned: cleaned, scrubbed: scrubbed };
}

// FROM v2 line 20635 — protocol number regex. Excludes false positives
// where the captured value starts with "cp" or "ref" (those are CP refs,
// not protocol numbers). Used by init's Word.run protocol scan.

engine.extractProtocol:
function extractProtocol(text) {
  if (!text) return "";
  var re = /protocol\s*(?:no\.?|number|#)\s*[:\-]?\s*([A-Za-z0-9][A-Za-z0-9\-_\/\.]{2,})/i;
  var m = String(text).match(re);
  if (!m) return "";
  var val = m[1].trim();
  if (/^(?:cp\b|ref\b)/i.test(val)) return "";
  return val;
}

// FROM v2 line 20413 — format `additional_participants` array into the
// CCs textarea string. Skips entries with name "Unknown" — the AI emits
// that placeholder when it found an email but no associated name.

engine.formatParticipantsCcs:
function formatParticipantsCcs(participants) {
  if (!Array.isArray(participants)) return "";
  return participants
    .filter(function (p) { return p && (p.email || p.name); })
    .map(function (p) {
      if (p.name && p.name !== "Unknown" && p.email) return p.name + "<" + p.email + ">";
      return p.email || p.name || "";
    })
    .filter(Boolean)
    .join(", ");
}

// FROM v2 line 20428 — fuzzy-match agreement type from raw text against a
// list of options. Returns the best-scoring index, or -1 if no match.
// Used by the view to pre-select the type dropdown from AI-extracted text.

engine.matchAgTypeIndex:
function matchAgTypeIndex(rawText, options) {
  var raw = String(rawText || "").toLowerCase().replace(/[^a-z ]/g, "").trim();
  if (!raw) return -1;
  var rules = [
    { key: "research", score: 100 }, { key: "disclosure", score: 100 },
    { key: "confidential", score: 100 }, { key: "nda", score: 100 },
    { key: "material", score: 100 }, { key: "transfer", score: 50 },
    { key: "mta", score: 100 }, { key: "master", score: 100 },
    { key: "service", score: 30 }, { key: "amendment", score: 100 },
    { key: "clinical", score: 100 }, { key: "joint", score: 100 },
    { key: "development", score: 50 }, { key: "agreement", score: 0 },
  ];
  var bestIdx = -1, bestScore = 0;
  for (var i = 0; i < options.length; i++) {
    var opt = String(options[i] || "").toLowerCase();
    var s = 0;
    if (opt === raw) s += 500;
    for (var k = 0; k < rules.length; k++) {
      if (raw.indexOf(rules[k].key) !== -1 && opt.indexOf(rules[k].key) !== -1) s += rules[k].score;
    }
    if (opt.indexOf("master") !== -1 && raw.indexOf("master") === -1) s -= 50;
    if (s > bestScore) { bestScore = s; bestIdx = i; }
  }
  return bestScore > 0 ? bestIdx : -1;
}

