  var subjTp  = root.querySelector("#_eli3_ae_tmpl_subj_tp");
  var bodyTp  = root.querySelector("#_eli3_ae_tmpl_body_tp");
  var subjReq = root.querySelector("#_eli3_ae_tmpl_subj_req");
  var bodyReq = root.querySelector("#_eli3_ae_tmpl_body_req");
  var prev = "__default";

  function _stash(key) {
    cache[key] = {
      thirdParty: { subject: subjTp.value, body: bodyTp.value },
      requester:  { subject: subjReq.value, body: bodyReq.value },
    };
  }
  function _load(key) {
    var src = cache[key] || cache.__default;
    subjTp.value  = src.thirdParty.subject || "";
    bodyTp.value  = src.thirdParty.body    || "";
    subjReq.value = src.requester.subject  || "";
    bodyReq.value = src.requester.body     || "";
    if (key === "__default") {
      hintEl.textContent = "Editing the default template used for all agreement types.";
      resetBtn.style.display = "none";
    } else {
      hintEl.textContent = cache[key]
        ? "Custom template for “" + key + "”."
        : "Using default template. Edit to customize for this type.";
      resetBtn.style.display = cache[key] ? "" : "none";
    }
  }
  _load("__default");

  typeSel.onchange = function () {
    _stash(prev);
    prev = typeSel.value;
    _load(prev);
  };
  resetBtn.onclick = function () {
    delete cache[typeSel.value];
    _load(typeSel.value);
  };

  root.querySelector("#_eli3_ae_tmpl_save").onclick = function () {
    _stash(prev);
    var byType = {};
    Object.keys(cache).forEach(function (k) {
      if (k !== "__default") byType[k] = cache[k];
    });
    onSave({
      myName: root.querySelector("#_eli3_ae_tmpl_myname").value.trim(),
      useFullName: root.querySelector("#_eli3_ae_tmpl_useFull").checked,
      thirdParty: cache.__default.thirdParty,
      requester:  cache.__default.requester,
      byType: byType,
    });
  };

  mount.appendChild(root);
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["auto_emailer"];
  if (!bundle) return;
  var renderComposer = bundle._eliViewFns && bundle._eliViewFns.renderComposer;
  var renderTemplatesPanel = bundle._eliViewFns && bundle._eliViewFns.renderTemplatesPanel;
  var shapeEmailTemplates = bundle._eliEngineFns && bundle._eliEngineFns.shapeEmailTemplates;
  var buildGmailUrl = bundle._eliEngineFns && bundle._eliEngineFns.buildGmailUrl;
  var matchAgTypeIndex = bundle._eliEngineFns && bundle._eliEngineFns.matchAgTypeIndex;
  var cleanAiPrefill = bundle._eliEngineFns && bundle._eliEngineFns.cleanAiPrefill;
  var formatParticipantsCcs = bundle._eliEngineFns && bundle._eliEngineFns.formatParticipantsCcs;
  var extractProtocol = bundle._eliEngineFns && bundle._eliEngineFns.extractProtocol;

  if (!renderComposer || !shapeEmailTemplates || !buildGmailUrl) {
    eli.log.event("tool", "auto_emailer_load_failed", {
      hasView: !!renderComposer,
      hasShape: !!shapeEmailTemplates,
      hasBuildUrl: !!buildGmailUrl,
    });
    return;
  }

  function _recordStatSafe(name) {
    try {
      if (eli.stats && typeof eli.stats.record === "function") eli.stats.record(name);
    } catch (e) {
      eli.log.event("tool", "auto_emailer_stat_failed", { stat: name, msg: e && e.message });
    }
  }

  // FROM v2 line 20290 — persist user-edited values back to doc settings
  // so the next emailer open (any user, any machine) skips AI roundtrip.
  function _persistDocPrefill(patch) {
    if (!patch) return;
    try {
      var s = Office.context.document.settings;
      var current = s.get("EliEmailerPrefill") || {};
      Object.keys(patch).forEach(function (k) {
        if (patch[k] == null || patch[k] === "") delete current[k];
        else current[k] = patch[k];
      });
      s.set("EliEmailerPrefill", current);
      if (typeof s.saveAsync === "function") {
        s.saveAsync(function (res) {
          if (res && res.status !== Office.AsyncResultStatus.Succeeded) {
            eli.log.event("tool", "auto_emailer_persist_failed", { msg: res.error && res.error.message });
          }
        });
      }
    } catch (e) {
      eli.log.event("tool", "auto_emailer_persist_threw", { msg: e && e.message });
    }
  }

  function _readDocPrefill() {
    try {
      var cached = Office.context.document.settings.get("EliEmailerPrefill");
      if (cached && typeof cached === "object") return cached;
    } catch (e) { /* tolerate */ }
    return {};
  }

  // FROM v2 line 20265-20282 — OARS-priority agreement type. The user
  // explicitly chose a type at OARS load time (persisted to doc settings
  // as AgreementDataDetails.type); that wins over whatever the AI sniffed.
  // Returns "" if no OARS type is set.
  function _readOarsAgreementType() {
    try {
      var details = Office.context.document.settings.get("AgreementDataDetails");
      if (details && typeof details.type === "string") {
        var t = details.type.trim();
        if (t && t.toLowerCase() !== "local") return t;
      }
    } catch (e) { /* tolerate */ }
    return "";
  }

  // FROM v2 line 20294-20310 — initial-load persist. Whitelisted snapshot
  // of the seeded prefill so OTHER sessions (different machine, different
  // user opening the same doc) skip the AI roundtrip even if the user
  // closes the modal without editing.
  var PREFILL_FIELDS = [
    "type", "agreement_type", "colgate_entity", "entity",
    "third_party_entity", "contact_full_name", "contact_email",
    "requester_name", "requester_email", "cp_ref",
    "additional_participants",
  ];
  function _persistInitialPrefill(prefill) {
    if (!prefill || typeof prefill !== "object") return;
    var snap = {};
    PREFILL_FIELDS.forEach(function (k) {
      var v = prefill[k];
      var keep = v != null && v !== "" && !(Array.isArray(v) && v.length === 0);
      if (keep) snap[k] = v;
    });
    if (!Object.keys(snap).length) return;
    try {
      var s = Office.context.document.settings;
      s.set("EliEmailerPrefill", snap);
      if (typeof s.saveAsync === "function") s.saveAsync(function () {});
    } catch (e) { /* tolerate */ }
  }

  // Open the composer. `seed` overrides doc-settings prefill (used when
  // build_draft hands off after save).
  function _open(seed) {
    if (!eli.ai || !eli.ai.hasApiKey()) {
      // Emailer doesn't directly call AI, but agreement_types data and
      // future AI-prefill paths assume the kernel is API-key-warm.
      // Keep this soft — open anyway, just with a hint.
      eli.log.event("tool", "auto_emailer_open_no_ai_key", {});
    }
    var mount = document.getElementById("_eli3_dashboard_root");
    var prefillBase = seed || _readDocPrefill();
    if (seed) {
      // Layer doc-settings on top for fields seed didn't populate
      // (typical: build_draft seeds entity/type/tp/ref but not contact/req).
      var stored = _readDocPrefill();
      ["contact_full_name", "contact_email", "requester_name", "requester_email", "additional_participants"]
        .forEach(function (k) {
          if (stored[k] && !prefillBase[k]) prefillBase[k] = stored[k];
        });
    }

    // FROM v2 line 20242-20251 — scrub MIME junk from type/agreement_type
    // before anything else uses these values.
    if (cleanAiPrefill) {
      var scrubResult = cleanAiPrefill(prefillBase);
      prefillBase = scrubResult.cleaned;
      if (scrubResult.scrubbed.length && typeof showToast === "function") {
        scrubResult.scrubbed.forEach(function (k) { showToast("🧹 Auto-cleaned: " + k, "info"); });
      }
    }

    // OARS-priority agreement type — overrides AI/seed.
    var oarsType = _readOarsAgreementType();
    if (oarsType) {
      prefillBase.type = oarsType;
      prefillBase.agreement_type = oarsType;
    }

    // Default to Colgate entity when neither AI nor seed specified one.
    // FROM v2 line 20252-20259.
    if (!prefillBase.colgate_entity && !prefillBase.entity) {
      prefillBase.colgate_entity = "Colgate-Palmolive";
    }

    // Persist the cleaned snapshot now (before user edits) so other
    // sessions can skip AI even if this one's closed without saving.
    _persistInitialPrefill(prefillBase);

    // Pull agreement types + saved requesters + email templates in parallel.
    Promise.all([
      eli.events.safeAsync(eli.storage.getAll("agreement_types"), "auto_emailer.ag_types"),
      eli.events.safeAsync(eli.storage.getAll("requesters"),      "auto_emailer.requesters"),
      eli.events.safeAsync(eli.storage.getAll("email_templates"), "auto_emailer.templates"),
    ]).then(function (results) {
      var agRows  = results[0] || [];
      var reqRows = results[1] || [];
      var tplRows = results[2] || [];
      var agTypes = agRows
        .filter(function (r) { return r && !r.pseudo; })
        .map(function (r) { return r.label || r.name || r.id; })
        .filter(Boolean);
      var requesters = reqRows
        .filter(function (r) { return r && r.id && (r.name || r.email); })
        .map(function (r) { return { id: String(r.id), name: r.name || "", email: r.email || "" }; });
      var templates = shapeEmailTemplates(tplRows);

      _renderWith({
        mount: mount,
        prefill: prefillBase,
        agTypes: agTypes,
        requesters: requesters,
        templates: templates,
        defaultDest: "tp",
        autoSelectId: null,
      });
    });
  }

  function _renderWith(state) {
    renderComposer({
      mount: state.mount,
      prefill: state.prefill || {},
      agTypes: state.agTypes,
      requesters: state.requesters,
      defaultDest: state.defaultDest,
      autoSelectId: state.autoSelectId,
      matchAgTypeIndex: matchAgTypeIndex,
      formatParticipantsCcs: formatParticipantsCcs || function () { return ""; },
      onBack: function () {
        if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
        else if (eli.dashboard && typeof eli.dashboard.render === "function") eli.dashboard.render();
      },
      onPersistPrefill: _persistDocPrefill,
      onSaveRequester: eli.events.guard(function (newReq) {
        var id = String(Date.now());
        var row = { id: id, name: newReq.name, email: newReq.email };
        eli.events.safeAsync(eli.storage.put("requesters", row), "auto_emailer.req_save").then(function () {
          if (typeof showToast === "function") showToast("✅ Requester saved", "ok");
          state.requesters = state.requesters.concat([row]);
          state.autoSelectId = id;
          _renderWith(state);
        });
      }, "auto_emailer.req_save_outer"),
      onDeleteRequester: function (id) {
        eli.ui.confirm({
          title: "Delete Requester?",
          message: "This removes them from your saved list permanently.",
          variant: "danger",
        }).then(function (ok) {
          if (!ok) return;
          eli.events.safeAsync(eli.storage.delete("requesters", id), "auto_emailer.req_del").then(function () {
            state.requesters = state.requesters.filter(function (r) { return String(r.id) !== String(id); });
            state.autoSelectId = null;
            if (typeof showToast === "function") showToast("🗑️ Removed", "ok");
            _renderWith(state);
          });
        });
      },
      onOpenGmail: function (form) {
        return _scanProtocolNumber().then(function (protocol) {
          form.protocol = protocol || "";
          var url = buildGmailUrl(form, state.templates || shapeEmailTemplates([]));
          _openUrl(url, form);
          return null;
        });
      },
    });
  }

  // Word.run scan for [Protocol] token. FROM v2 line 20634-20668 —
  // body first, then per-section FirstPage + Primary headers. Returns ""
  // when no match (URL just has empty [Protocol] substitution).
  function _scanProtocolNumber() {
    if (!extractProtocol || !eli.host || !eli.host.runRaw) return Promise.resolve("");
    return eli.host.runRaw("auto_emailer:protocol_scan", function (context) {
      var body = context.document.body;
      var sections = context.document.sections;
      body.load("text");
      sections.load("items");
      return context.sync().then(function () {
        var bodyHit = extractProtocol(body.text);
        if (bodyHit) return bodyHit;
        var headers = [];
        for (var i = 0; i < sections.items.length; i++) {
          ["FirstPage", "Primary"].forEach(function (kind) {
            try { headers.push(sections.items[i].getHeader(kind)); } catch (e) {}
          });
        }
        headers.forEach(function (r) { try { r.load("text"); } catch (e) {} });
        return context.sync().then(function () {
          for (var j = 0; j < headers.length; j++) {
            var hit = extractProtocol(headers[j].text || "");
            if (hit) return hit;
          }
          return "";
        });
      });
    }).catch(function (err) {
      eli.log.event("tool", "auto_emailer_protocol_scan_failed", { msg: err && err.message });
      return "";
    });
  }

  function _openUrl(url, form) {
    _recordStatSafe("emailsDrafted");
    if (eli.activity && eli.activity.add) {
      eli.activity.add({
        type: "auto-emailer", icon: "✉️", label: "Auto Emailer · Draft",
        summary: "Drafted " + (form.dest === "req" ? "to requester" : "to TP") + " · " + (form.type || "?"),
        payload: { dest: form.dest, type: form.type, third_party: form.third_party_entity },
      });
    }
    try {
      if (Office.context.ui && typeof Office.context.ui.openBrowserWindow === "function") {
        Office.context.ui.openBrowserWindow(url);
      } else {
        window.open(url, "_blank");
      }
    } catch (e) {
      window.open(url, "_blank");
    }
  }

  // ─── Templates panel (gear icon) ──────────────────────────────────────
  // FROM v2 showConfigModal('email') (line 13833+). Edits the email
  // template subject + body for TP / Requester emails — both default and
  // per-agreement-type overrides — plus My Name / Use Full Name signature
  // settings. Persists to STORE_EMAIL_TEMPLATES with the same row shape
  // the engine's shapeEmailTemplates reads.
  function _openTemplatesPanel() {
    if (!renderTemplatesPanel) {
      if (typeof showToast === "function") showToast("Templates panel not loaded.", "warn");
      return;
    }
    var mount = document.getElementById("_eli3_dashboard_root");
    Promise.all([
      eli.events.safeAsync(eli.storage.getAll("agreement_types"), "auto_emailer.tmpl_ag_types"),
      eli.events.safeAsync(eli.storage.getAll("email_templates"), "auto_emailer.tmpl_load"),
    ]).then(function (results) {
      var agTypes = (results[0] || [])
        .filter(function (r) { return r && !r.pseudo; })
        .map(function (r) { return r.label || r.name || r.id; })
        .filter(Boolean);
      var templates = shapeEmailTemplates(results[1] || []);
      // FROM v2 getEmailTemplates (line 2809) — myName + useFullName live
      // in localStorage `eli_user_settings.emailTemplates`, NOT IDB. v3
      // moved them to IDB but still falls back to v2's location so existing
      // installs see their saved name. Final fallback: derive first name
      // from user identity.
      if (!templates.myName) {
        try {
          var raw = eli.compat.lsGet("eli_user_settings");
          var s = raw ? JSON.parse(raw) : null;
          if (s && s.emailTemplates && s.emailTemplates.myName) {
            templates.myName = s.emailTemplates.myName;
            templates.useFullName = !!s.emailTemplates.useFullName;
          }
        } catch (e) { /* malformed JSON — ignore */ }
      }
      if (!templates.myName && eli.tools && typeof eli.tools.userIdentity === "function") {
        try {
          var id = eli.tools.userIdentity() || {};
          templates.myName = id.firstName || id.name || "";
        } catch (e) { /* tolerate */ }
      }
      renderTemplatesPanel({
        mount: mount,
        templates: templates,
        agTypes: agTypes,
        onBack: function () {
          if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
          else if (eli.dashboard && typeof eli.dashboard.render === "function") eli.dashboard.render();
        },
        onSave: eli.events.guard(function (form) {
          _saveTemplates(form).then(function () {
            if (typeof showToast === "function") showToast("✅ Templates saved", "ok");
            if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
            else if (eli.dashboard && typeof eli.dashboard.render === "function") eli.dashboard.render();
          }).catch(function (err) {
            eli.log.event("tool", "auto_emailer_tmpl_save_failed", { msg: err && err.message });
            if (typeof showToast === "function") showToast("Save failed: " + (err && err.message), "err");
          });
        }, "auto_emailer.tmpl_save"),
      });
    });
  }

  // Persist the form back to IDB. Writes 4 rows mirroring v2's shape so
  // shapeEmailTemplates reads them back correctly. Also mirrors myName +
  // useFullName to v2's `eli_user_settings.emailTemplates` so the v2
  // kernel (or other v2-aware paths) see the same value.
  function _saveTemplates(form) {
    var rows = [
      { id: "thirdParty", subject: (form.thirdParty || {}).subject || "", body: (form.thirdParty || {}).body || "" },
      { id: "requester",  subject: (form.requester  || {}).subject || "", body: (form.requester  || {}).body || "" },
      { id: "byType",     byType: form.byType || {} },
      { id: "settings",   myName: form.myName || "", useFullName: !!form.useFullName },
    ];
    var ops = rows.map(function (r) {
      return eli.storage.put("email_templates", r);
    });
    // Mirror to v2 localStorage. Best-effort — never block save on failure.
    try {
      var raw = eli.compat.lsGet("eli_user_settings");
      var s = {};
      if (raw) { try { s = JSON.parse(raw) || {}; } catch (e) { s = {}; } }
      if (!s.emailTemplates) s.emailTemplates = {};
      s.emailTemplates.myName = form.myName || "";
      s.emailTemplates.useFullName = !!form.useFullName;
      eli.compat.lsSet("eli_user_settings", JSON.stringify(s));
    } catch (e) {
      eli.log.event("tool", "auto_emailer_v2_settings_mirror_failed", { msg: e && e.message });
    }
    return Promise.all(ops);
  }

  // Register channels:
  //   tile / app_auto_emailer       — main click from dashboard
  //   tile_settings / app_auto_emailer — gear icon → templates editor
  //   auto_emailer:compose          — programmatic launch with a seed
  //                                    payload (used by build_draft post-save)
  eli.register({
    tile: { app_auto_emailer: function () {
      _recordStatSafe("appOpenedAutoEmailer");
      _open(null);
    } },
    tile_settings: { app_auto_emailer: function () {
      _recordStatSafe("appOpenedAutoEmailerTemplates");
      _openTemplatesPanel();
    } },
    auto_emailer: { compose: function (seed) {
      _recordStatSafe("appOpenedAutoEmailer");
      _open(seed || null);
    } },
  });

  eli.log.event("tool", "auto_emailer_initialized", {});
}

jsonTools.css:
/* auto_emailer tool styles. Injected as <style data-tool="auto_emailer">. */

._eli3_ae_root {
  display: flex; flex-direction: column;
  width: 100%; height: 100%;
  background: #fff;
  overflow: hidden;
  box-sizing: border-box;
}
/* Standard tool-hub header — dark navy banner with gold accent rule. */
._eli3_ae_bar {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 10px;
  padding: 12px 14px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 3px solid #c9a227;
}
._eli3_ae_back {
  background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #cbd5e1;
  padding: 0 4px;
  transition: color 0.15s;
}
._eli3_ae_back:hover { color: #f2d866; }
._eli3_ae_title {
  flex: 1;
  font: 800 16px/1.2 'Georgia', serif;
  color: #ffffff;
  letter-spacing: 0.2px;
}

/* Form body */
._eli3_ae_form {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 14px;
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_ae_label {
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #0f172a;
  margin-top: 6px;
}
._eli3_ae_input {
  width: 100%;
  padding: 8px 10px;
  border: 1px solid #cbd5e1;
  background: #fff;
  font: 500 13px/1.3 'Inter', sans-serif;
  color: #0f172a;
  box-sizing: border-box;
  outline: none;
}
._eli3_ae_input:focus {
  border-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21, 101, 192, 0.18);
}
._eli3_ae_grid2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

/* Destination (TP / Requester) toggle */
._eli3_ae_dest {
  display: flex; gap: 18px;
  padding: 10px 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  margin-bottom: 6px;
}
._eli3_ae_dest_opt {
  display: inline-flex; align-items: center; gap: 6px;
  font: 600 12px/1 'Inter', sans-serif;
  color: #1e293b;
  cursor: pointer;
}
._eli3_ae_dest_opt input[type="radio"] {
  margin: 0; accent-color: #1565c0;
}

/* Requester picker box */
._eli3_ae_req_box {
  margin-top: 10px;
  padding: 10px 12px;
  background: #eff6ff;
  border: 1px solid #93c5fd;
}
._eli3_ae_req_head {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 6px;
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #1565c0;
}
._eli3_ae_req_del {
  background: none; border: none;
  color: #c62828;
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  cursor: pointer;
}
._eli3_ae_req_del:hover { color: #8e1d1d; text-decoration: underline; }
._eli3_ae_req_manual {
  margin-top: 10px;
  padding-top: 10px;
  border-top: 1px dashed #93c5fd;
  display: flex; flex-direction: column; gap: 6px;
}
._eli3_ae_req_manual_btns {
  display: flex; gap: 8px;
  margin-top: 4px;
}
._eli3_ae_req_manual_btns ._eli3_ae_skip { flex: 1; }

/* Add Participants toggle (closed state) — small inline link. */
._eli3_ae_addcc_toggle {
  margin-top: 10px;
  font: 700 10px/1.2 'Inter', sans-serif;
  color: #1565c0;
  cursor: pointer;
  display: inline-block;
  user-select: none;
}
._eli3_ae_addcc_toggle:hover { color: #0d47a1; text-decoration: underline; }

/* Open state — green box matching v2 line 20411 (#f1f8e9 / #c5e1a5). */
._eli3_ae_addcc_box {
  margin-top: 10px;
  padding: 10px 12px;
  background: #f1f8e9;
  border: 1px solid #c5e1a5;
}

/* CCs textarea */
._eli3_ae_ccs {
  font-family: 'JetBrains Mono', monospace;
  height: 56px;
  resize: vertical;
}
._eli3_ae_hint {
  font: 400 10px/1 'Inter', sans-serif;
  color: #94a3b8;
  text-transform: none;
  letter-spacing: 0;
  margin-left: 4px;
}

/* Action row — Skip / Open Gmail Draft */
._eli3_ae_actions {
  display: flex;
  gap: 8px;
  margin-top: 14px;
}
._eli3_ae_skip {
  flex: 1;
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.4px;
  color: #475569;
  padding: 10px 14px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_ae_skip:hover {
  background: linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%);
  color: #0f172a;
  border-color: #94a3b8;
}
._eli3_ae_btn {
  flex: 1.6;
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  font: 700 12px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  padding: 10px 14px;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: 0 2px 6px rgba(21, 101, 192, 0.25);
}
._eli3_ae_btn:hover:not(:disabled) {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(21, 101, 192, 0.35);
}
._eli3_ae_btn:disabled { opacity: 0.6; cursor: progress; }
._eli3_ae_btn_icon { font-size: 14px; line-height: 1; }
._eli3_ae_btn_label { white-space: nowrap; }

/* =====================================================================
   Templates editor (renderTemplatesPanel)
   ===================================================================== */
._eli3_ae_tmpl_typebox {
  margin-top: 12px;
  padding: 10px 12px;
  background: #fff8e1;
  border: 1px solid #ffe082;
}
._eli3_ae_tmpl_hint {
  font: 500 10px/1.4 'Inter', sans-serif;
  color: #7a5d2a;
  font-style: italic;
  margin-top: 6px;
}
._eli3_ae_tmpl_block {
  margin-top: 12px;
  padding: 12px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}
._eli3_ae_tmpl_block_req {
  background: #eff6ff;
  border-color: #93c5fd;
}
._eli3_ae_tmpl_block_head {
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #37474f;
  padding-bottom: 5px;
  margin-bottom: 8px;
  border-bottom: 1px solid #cbd5e1;
}
._eli3_ae_tmpl_block_req ._eli3_ae_tmpl_block_head {
  color: #1565c0;
  border-bottom-color: #93c5fd;
}
._eli3_ae_tmpl_textarea {
  height: 110px;
  font-family: 'Inter', sans-serif;
  line-height: 1.45;
  resize: vertical;
}
._eli3_ae_tmpl_resetrow {
  margin-top: 8px;
  display: flex;
  justify-content: flex-end;
}
._eli3_ae_tmpl_reset {
  flex: 0 0 auto;
}
._eli3_ae_tmpl_tokens {
  margin-top: 12px;
  padding: 8px 10px;
  background: #f1f5f9;
  border: 1px solid #cbd5e1;
  font: 600 10px/1.5 'JetBrains Mono', monospace;
  color: #475569;
}
